          "Meta’s inauthentic-engagement announcement described action against fake likes, views and follower services in 2019. This historical material explains a platform position; it does not certify any present supplier demonstration.\n\nA number remaining visible on an account therefore does not establish that the platform verified genuine interest behind it. Platform action against inauthentic activity also cannot become a promise that the brand can identify every anomaly.\n\nFree does not alter that logic. A zero price supplies no evidence about action sources or audience choice and does not turn a demonstration into a platform-approved partnership method.\n\nEducational guidance should explain fact and inference together: the platform publicly opposes inauthentic engagement, while the support for a particular claim depends on the actual material received. An institutional name or familiar interface cannot lend authority that the evidence itself lacks. This prevents both overconfidence in a supplier and overconfidence in the reviewer's ability to classify the underlying accounts."
