          "有时对方说，必须先连接账号才能展示效果。此时问题已从阅读资料，变成新的权限决定，不能由普通研究者为了补齐证据代为执行。\n\nMeta 的 Instagram 安全说明提出检查登录活动、恢复资料与双重验证等保护措施。它是带日期的指导，实际处理应由账号所有者通过当前官方路径确认。\n\n品牌可以说明不接受以提交凭证或验证码作为研究前提，也不将演示过程中的不明操作写成正常合作步骤。已有风险由有权人员处理，不在教育文章里复现领取流程。\n\n拒绝提供访问，意味着这条核验路线不采用，不等于已经证明对方盗号。保留准确的拒绝理由，就能同时保护账号和事实边界，而不需要给未知动机补上指控。",
          "Sometimes a sender says the account must be connected before they can demonstrate results. The question has then moved from interpreting information to authorizing access. An ordinary researcher should not perform that operation merely to complete an evidence file.\n\nMeta’s Instagram security guide discusses login activity, recovery details and two-factor protection. It is dated guidance; the owner should confirm actual handling through current official routes.\n\nThe brand can reject submission of credentials or codes as a research prerequisite and avoid presenting unclear demonstration operations as normal partnership steps. Authorized people handle existing concerns; an educational article need not reproduce a claiming sequence.\n\nDeclining access means that verification route will not be used, not that account theft has been established. Preserve the actual reason for declining to protect both the account and the factual boundary. A reviewer does not need to speculate about hidden motives in order to decide that an unnecessary permission request is outside the scope of the project."
