          "FTC 的虚假影响力指标问答在美国语境下说明，真实的人选择关注品牌，与虚假指标不同；相关购买条款包含知道或应当知道的条件。这不是对每个数字的自动鉴定。\n\n演示若使用“真人”一词，仍需理解它实际要表达什么。存在一个真实账号，不会自动证明该动作表达了对品牌或产品的真实兴趣。\n\n也不能仅凭演示涉及增长，就把创作者正常介绍品牌、观众自愿回应的合作视为虚假采购。先核对实际行为，不按关键词给个人或项目定性。\n\n本文不判断某位供应商或创作者的责任。团队若面对具体商业事实与市场规则，应交给合适负责人处理；教育材料的作用，是避免把有限观察扩大成认证或指控。",
          "FTC’s fake-influence-indicator Q&A explains, in its United States context, that real people choosing to follow a brand differ from fake indicators, and the relevant purchase provision includes a knew-or-should-have-known condition. This is not automatic classification of every number.\n\nIf a demonstration uses real people, establish what that phrase is intended to mean. The existence of a real account does not automatically prove that its action expresses genuine interest in the brand or product.\n\nConversely, a demonstration concerning growth does not make a normal creator introduction followed by voluntary audience response a fake-indicator purchase. Examine the actual activity rather than assign a label from the keyword.\n\nThis article determines no supplier's or creator's liability. Specific commercial facts and market rules belong with an appropriate owner. The educational purpose is to prevent a limited observation becoming either certification or accusation. It should help colleagues know which questions remain open without inviting them to treat a general rule description as an individual finding."
