          "Where evidence is insufficient, the brand can decide not to use the demonstration for shortlist scores, renewal judgements or outcome publicity. Specify the affected use instead of declaring all data invalid.\n\nThe free-follower offer review method helps prioritize handling. Access questions go to the owner, data questions retain definitions, and content review can continue against the actual task. One issue should not replace another.\n\nIf more information arrives, update the corresponding state while retaining versions. A new explanation should not silently overwrite the earlier record, especially when the demonstration has already been copied into several documents.\n\nGive users clear limits: which checked fact can be cited, which marketing conclusion must not be adopted and who approves a change. A research note without a sharing rule can still allow the same material to be overinterpreted in the next report. The useful output therefore connects evidence status to actual document use, rather than assuming everybody will remember a caveat that appeared only in an original email."
